ith open('/app/resources/treasury_bulletin_2013_06.json', 'r') as f:\n    data = json.load(f)\n\ndoc = data['document']\npages = doc.get('pages', [])\n\n# Search all pages for any reference to Dec 31, 2013\nfor i, page in enumerate(pages):\n    page_content = str(page)\n    if '2013' in page_content and 'Dec' in page_content:\n        print(f\"Page {i} might have 2013 Dec data\")\n        # Show first 200 chars\n        print(page_content[:300])\n        print(\"---\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
